function SVo(a) {
    const n = {};
    n["VkGjo"] = "number",
    n["NQaHS"] = function(o, c) {
        return o < c
    }
    ,
    n.cYCbC = function(o, c) {
        return o * c
    }
    ;
    const t = n;
    let r = a
      , s = "";
    const i = "ABCDEFGHJKMNPQRSTWXYZabcdefhijkmnprstwxyz";
    t["VkGjo"] == typeof a && a || (r = -349 * -25 + 1118 + -9811);
    for (let o = -2437 * 4 + 5 * -245 + 10973; t.NQaHS(o, r); o++)
        s += i.charAt(Math.floor(t.cYCbC(1765 + 5792 + -7516, Math["random"]())));
    return s
}
// console.log(SVo(4))
function yVo(a, e) {
    const  t = {};
    t["dpfVG"] = function(s, i) {
        return s + i
    }
    ,
    t["WFihG"] = function(s, i) {
        return s * i
    }
    ;
    const r = t;
    return Math["round"](r.dpfVG(r["WFihG"](Math["random"](), e - a), a))
}
